agent-creator/SKILL.md:36:On Goose, load Skills only with `load_skill` (argument `name`: the installed name). If it is not a direct tool, confirm it with `list_functions`, then call `await tools.call("load_skill", { name })` inside `execute_javascript`. `load` and `delegate(source:)` resolve recipes, subrecipes and agents, never Skills; their "not found" does not prove a Skill is absent. Report a direct `SKILL.md` read as reading, not activation.
hook-creator/SKILL.md:36:On Goose, load Skills only with `load_skill` (argument `name`: the installed name). If it is not a direct tool, confirm it with `list_functions`, then call `await tools.call("load_skill", { name })` inside `execute_javascript`. `load` and `delegate(source:)` resolve recipes, subrecipes and agents, never Skills; their "not found" does not prove a Skill is absent. Report a direct `SKILL.md` read as reading, not activation.
plugin-creator/SKILL.md:20:On Goose, load Skills only with `load_skill` (argument `name`: the installed name). If it is not a direct tool, confirm it with `list_functions`, then call `await tools.call("load_skill", { name })` inside `execute_javascript`. `load` and `delegate(source:)` resolve recipes, subrecipes and agents, never Skills; their "not found" does not prove a Skill is absent. Report a direct `SKILL.md` read as reading, not activation.
plugin-script-packaging/SKILL.md:46:On Goose, load Skills only with `load_skill` (argument `name`: the installed name). If it is not a direct tool, confirm it with `list_functions`, then call `await tools.call("load_skill", { name })` inside `execute_javascript`. `load` and `delegate(source:)` resolve recipes, subrecipes and agents, never Skills; their "not found" does not prove a Skill is absent. Report a direct `SKILL.md` read as reading, not activation.
On Goose, load Skills only with `load_skill` (argument `name`: the installed name). If it is not a direct tool, confirm it with `list_functions`, then call `await tools.call("load_skill", { name })` inside `execute_javascript`. `load` and `delegate(source:)` resolve recipes, subrecipes and agents, never Skills; their "not found" does not prove a Skill is absent. Report a direct `SKILL.md` read as reading, not activation.
  const text = readFileSync(join(ROOT, "skills", "plugin-creator", "SKILL.md"), "utf-8");
  for (const name of ["skill-creator", "hook-creator", "agent-creator", "plugin-script-packaging"]) {
    assert.ok(text.includes(`${PLUGIN_NAME}:${name}`), `${name}: qualified specialist route`);
  }
  assert.match(text, /authoring harness's verified loading mechanism/);
  assert.match(text, /plugin-qualified or standalone names as actually installed/);
  assert.match(text, /If loading is unavailable, read available instructions directly and disclose the limitation/);
  assert.match(text, /Missing instructions or execution capability block the affected branch/);
  assert.match(text, /Missing specialists do not authorize guessed schemas or simulated handoffs/);
});

// Regression: an agent on Goose 1.57.0 called `load(source: <skill>)`, which only
// resolves recipes/agents, and concluded the Skill was missing. Every routing Skill
// must name the functional Goose call and reject the look-alike tools.
test("routing Skills name the functional Goose Skill-loading call", () => {
  for (const name of ["plugin-creator", "agent-creator", "hook-creator", "plugin-script-packaging"]) {
    const text = readFileSync(join(SKILLS, name, "SKILL.md"), "utf-8");
    assert.match(text, /On Goose, load Skills only with `load_skill`/, `${name}: load_skill route`);
    assert.ok(text.includes('`await tools.call("load_skill", { name })` inside `execute_javascript`'), `${name}: code-mode call`);
    assert.match(text, /`load` and `delegate\(source:\)` resolve recipes, subrecipes and agents, never Skills/, `${name}: look-alike tools rejected`);
    assert.match(text, /direct `SKILL\.md` read as reading, not activation/, `${name}: fallback disclosure`);
  assert.match(plugin, /target host/); assert.match(plugin, /authoring harness/);
  assert.match(plugin, /candidate and judge execution identities/);
  for (const name of ['plugin-creator', 'plugin-script-packaging']) {
    const entry = readFileSync(join(SKILLS, name, 'SKILL.md'), 'utf8');
    assert.doesNotMatch(entry, /elapsed <seconds>s|first tick after 10 seconds|agent-plugin evaluation|Evaluation defaults:/);
    assert.match(entry, /only (?:what the user explicitly requests|when explicitly requested)/);
  }
  const skillEntry = join(SKILLS, 'skill-creator/SKILL.md');
  const skill = readFileSync(skillEntry, 'utf8');
  const evaluation = activeLinkedReference(skillEntry, 'references/evaluate-workflow.md');
  const commands = activeLinkedReference(skillEntry, 'references/command-contract.md#command-contract');
  activeLinkedReference(join(SKILLS, 'skill-creator/references/evaluate-workflow.md'), 'command-contract.md#command-contract');
  assert.doesNotMatch(skill, /first tick after 10 seconds|Evaluation defaults:|Suites are\s+found exactly/);
  assert.match(evaluation, /## Monitor heartbeat/);
  assert.match(evaluation, /### Configured candidate identity[^]*### Freeze and proceed/);
  assert.match(commands, /Evaluation defaults: Goose, configured model[^]*repetitions 3,\s+parallelism 3, max turns 50, timeout 0 and heartbeat enabled/);
  assert.match(commands, /Goose, configured model, 20 turns and 600 seconds/);
  assert.match(commands, /Export and helper\s+`--output` are optional/);
  const agent = readFileSync(join(SKILLS, 'agent-creator/SKILL.md'), 'utf8');
  assert.match(agent, /The authoring target is Goose/);
  assert.match(agent, /authoring harness may be another\s+host/);
  assert.match(agent, /never as Goose compatibility evidence/);
  const packaging = readFileSync(join(SKILLS, 'plugin-script-packaging/SKILL.md'), 'utf8');
  assert.match(packaging, /packaged language runtime\/toolchain is a separate executable closure/);
  assert.match(packaging, /For Goose Git installation confirm revision/);
});
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import path from 'node:path';
const root=path.resolve(import.meta.dirname,'..');
const read=(file:string)=>readFileSync(path.join(root,file),'utf8');
// Source snapshots are format evidence only: retired validators must not be replaced
// by successful mocks, and no test here claims installed native hook activation.
test('versioned evidence is separate from current host instructions',()=>{
 const source=read('skills/hook-creator/references/compatibility-matrix.md');
 assert.match(source,/v1\.47\.0[^\n]+f9c7aaccde4834810dfd13d5efa8f0d39ba28a20[^\n]+Absent/);
 assert.match(source,/main-2b17adc[^\n]+2b17adc33a7176e701c2fef9578a5fc5834ea89a[^\n]+observation only/);
 const active=read('skills/hook-creator/references/goose-target-compatibility.md');
 assert.match(active,/Only PreToolUse and Stop are blocking events/);
 assert.doesNotMatch(active,/v1\.47\.0|main-2b17adc/);
 assert.match(active,/`on_failure`/);assert.match(active,/Stop failures remain fail-open/);
});
test('source layout contract preserves native hooks and fails closed on ambiguous migration',()=>{
 const source=read('skills/hook-creator/references/goose-target-compatibility.md');
 assert.match(source,/<plugin>\/hooks\/hooks\.json/);
 assert.match(source,/not native activation paths/);
 assert.match(source,/Multiple layouts are rejected/);
 assert.match(source,/preserves native hooks and blocks adapter-only migration/);
 assert.match(source,/preserve manifest bytes/);
});
test('active hook instructions require manual component review, not retired validator success',()=>{
 const instructions=read('skills/hook-creator/SKILL.md');
 // Reject loss of manual review or revival of retired component validators, not wording changes.
 assert.match(instructions,/Manually review/);assert.match(instructions,/There is no current hook component\s+validator/);
 const goose=read('skills/hook-creator/references/goose-workflow.md');
 assert.match(goose,/supported events, compiling matchers, nonempty\s+commands, valid timeouts/);
 assert.match(instructions,/Direct handler success is not\s+lifecycle activation/);assert.match(instructions,/configuration review is not blocking-safety proof/);
 assert.match(instructions,/explicit local execution authority/);
 const mapping=JSON.parse(read('config/skill-runtimes/skill-runtime-map.json'));
 assert.ok(!mapping.skills.some((entry:any)=>entry.logicalName==='hook-creator'||entry.logicalName==='plugin-creator'));
});
// Detect eager Goose procedures or a broken route for an author targeting another host.
// These assertions cover source disclosure, not actual harness loading or activation.
test('hook entrypoint routes by target host and discloses the Goose procedure only at its branch',()=>{
 const instructions=read('skills/hook-creator/SKILL.md');
 assert.match(instructions,/target is where the hook will run, not necessarily the harness/);
 assert.match(instructions,/If the host is not identified, ask/);
 for(const host of ['goose','claude-code','codex','opencode']){
  assert.ok(instructions.includes(`references/${host}-hooks.md`));
  assert.ok(read(`skills/hook-creator/references/${host}-hooks.md`).length>0);
 }
 assert.match(instructions,/For Goose creation, modification or audit,\s+follow the \[Goose component workflow\]\(references\/goose-workflow\.md\)/);
 assert.match(instructions,/never load the Goose procedure as a fallback/);
 assert.doesNotMatch(instructions,/## Author or review a Goose component|## Verify Goose handlers|GOOSE_STOP_HOOK_BLOCK_CAP|\$\{PLUGIN_ROOT\}|on_failure: block/);
 const goose=read('skills/hook-creator/references/goose-workflow.md');
 assert.match(goose,/## Author or review a Goose component/);
 assert.match(goose,/\$\{PLUGIN_ROOT\}/);assert.match(goose,/GOOSE_STOP_HOOK_BLOCK_CAP/);
 assert.match(goose,/\[SKILL\.md\]\(\.\.\/SKILL\.md#verify-the-selected-component-and-hand-off\)/);
});

